//! Plonky3 hiding-FRI control for the maintained BLAKE3 permutation AIR.
//!
//! This proves a private collection of BLAKE3 *permutations* generated by the
//! upstream AIR. It intentionally has no public output or transcript binding:
//! it measures the real BLAKE3 constraints and ZK PCS, not an LLM Notary
//! receipt proof.

use std::{env, time::Instant};

use p3_baby_bear::{BabyBear, Poseidon2BabyBear};
use p3_blake3_air::{Blake3Air, NUM_BLAKE3_COLS};
use p3_challenger::DuplexChallenger;
use p3_commit::ExtensionMmcs;
use p3_dft::Radix2DitParallel;
use p3_field::{Field, extension::BinomialExtensionField};
use p3_fri::{FriParameters, HidingFriPcs};
use p3_merkle_tree::MerkleTreeHidingMmcs;
use p3_symmetric::{PaddingFreeSponge, TruncatedPermutation};
use p3_uni_stark::{StarkConfig, prove, verify};
use rand::{SeedableRng, rngs::SmallRng};

const DEFAULT_PERMUTATIONS: usize = 1;

fn permutations() -> usize {
    let count = env::var("P3_BLAKE3_PERMUTATIONS")
        .ok()
        .map(|value| value.parse::<usize>())
        .transpose()
        .expect("P3_BLAKE3_PERMUTATIONS must be a positive power of two")
        .unwrap_or(DEFAULT_PERMUTATIONS);
    assert!(
        count.is_power_of_two() && count > 0,
        "P3_BLAKE3_PERMUTATIONS must be a positive power of two"
    );
    count
}

fn main() {
    let permutations = permutations();
    type Val = BabyBear;
    type Challenge = BinomialExtensionField<Val, 4>;
    type Perm = Poseidon2BabyBear<16>;
    type Hash = PaddingFreeSponge<Perm, 16, 8, 8>;
    type Compress = TruncatedPermutation<Perm, 2, 8, 16>;
    type ValMmcs = MerkleTreeHidingMmcs<
        <Val as Field>::Packing,
        <Val as Field>::Packing,
        Hash,
        Compress,
        SmallRng,
        2,
        8,
        4,
    >;
    type ChallengeMmcs = ExtensionMmcs<Val, Challenge, ValMmcs>;
    type Dft = Radix2DitParallel<Val>;
    type Pcs = HidingFriPcs<Val, Dft, ValMmcs, ChallengeMmcs, SmallRng>;
    type Challenger = DuplexChallenger<Val, Perm, 16, 8>;
    type Config = StarkConfig<Pcs, Challenge, Challenger>;

    let mut rng = SmallRng::seed_from_u64(7);
    let perm = Perm::new_from_rng_128(&mut rng);
    let hash = Hash::new(perm.clone());
    let compress = Compress::new(perm.clone());
    let value_mmcs = ValMmcs::new(hash, compress, 0, rng);
    let challenge_mmcs = ChallengeMmcs::new(value_mmcs.clone());
    let fri = FriParameters::new_benchmark_zk(challenge_mmcs);
    let soundness_bits = fri.conjectured_soundness_bits();
    assert_eq!(soundness_bits, 216);
    let pcs = Pcs::new(
        Dft::default(),
        value_mmcs,
        fri,
        4,
        SmallRng::seed_from_u64(9),
    );
    let config = Config::new(pcs, Challenger::new(perm));
    let air = Blake3Air {};
    let trace = air.generate_trace_rows::<Val>(permutations, 0);

    let prove_start = Instant::now();
    let proof = prove(&config, &air, trace, &[]);
    let prove_elapsed = prove_start.elapsed();
    let proof_bytes = postcard::to_allocvec(&proof)
        .expect("proof must serialize")
        .len();

    let verify_start = Instant::now();
    verify(&config, &air, &proof, &[]).expect("proof must verify");
    let verify_elapsed = verify_start.elapsed();
    println!(
        "permutations={permutations} private_trace_cells={} zk_fri_soundness_bits={} prove_ms={} verify_ms={} proof_bytes={proof_bytes}",
        permutations * NUM_BLAKE3_COLS,
        soundness_bits,
        prove_elapsed.as_millis(),
        verify_elapsed.as_millis(),
    );
}
